///<reference path="../node_modules/grafana-sdk-mocks/app/headers/common.d.ts" />
import isEqual from 'lodash/isEqual';
import isObject from 'lodash/isObject';
import isUndefined from 'lodash/isUndefined';

export class GenericDatasource {
  current: any;
  name: string;
  q: any;
  backendSrv: any;
  templateSrv: any;
  withCredentials: boolean;
  headers: any;
  username:any;
  userPassword: any;
  premise: string;
  baseUrl: string;
  module = 'procdevstats';
  private expiresAt = 0;
  private authToken = null;
  private loginApiUrl = '/netq/auth/v1/login';
  private premiseUrl = '/netq/auth/v1/select/opid/';
  private grafanaEndpointUrl = '/netq/telemetry/v1/object/';

  /** @ngInject **/
  constructor(instanceSettings, $q, backendSrv, templateSrv) {
    this.name = instanceSettings.name;
    this.baseUrl = instanceSettings.jsonData.base_url;
    this.q = $q;
    this.backendSrv = backendSrv;
    this.templateSrv = templateSrv;
    this.withCredentials = true;
    this.headers = { 'Content-Type': 'application/json' };
    this.username = instanceSettings.jsonData.username;
    this.userPassword = instanceSettings.jsonData.userPass;
    this.premise = instanceSettings.jsonData.premise;
    this.module = instanceSettings.jsonData.module;
  }

  query(options) {
    const query = options;
    query.targets = this.buildQueryTargets(options);

    if (query.targets.length <= 0) {
      return this.q.when({ data: [] });
    }

    if (this.templateSrv.getAdhocFilters) {
      query.adhocFilters = this.templateSrv.getAdhocFilters(this.name);
    } else {
      query.adhocFilters = [];
    }

    query.scopedVars = this.getScopedVariables(Object.assign({}, options.scopedVars));

    return this.doRequest({
      urlAppend: `/query`,
      data: query,
      method: 'POST',
    });
  }

  testDatasource() {
    return this.doRequest({
      urlAppend: `/`,
      method: 'GET',
    }).then((response) => {
      if (response && response.status === 200) {
        return { status: 'success', message: 'Data source is working', title: 'Success' };
      }

      return {
        status: 'error',
        message: `Data source is not working: ${response.message}`,
        title: 'Error',
      };
    });
  }

  annotationQuery(options) {
    this.query(options);
  }

  metricFindQuery(query) {
    const interpolated = {
      target: this.templateSrv.replace(query, null, 'regex'),
    };

    return this.doRequest({
      urlAppend: `/search`,
      data: interpolated,
      method: 'POST',
    }).then(this.mapToTextValue);
  }

  mapToTextValue(result) {
    return result.data.map((d, i) => {
      if (d && d.text && d.value) {
        return { text: d.text, value: d.value };
      }

      if (isObject(d)) {
        return { text: d, value: i };
      }
      return { text: d, value: d };
    });
  }

  doRequest(options) {
    const append = options.urlAppend ? options.urlAppend : '';
    options.url = this.baseUrl + this.grafanaEndpointUrl + this.module + append;
    options.headers = this.headers;
    if (!this.authToken || this.expiresAt <= new Date().getTime()) {
      return this.backendSrv.datasourceRequest({
        url: this.baseUrl + this.loginApiUrl,
        method: 'POST',
        headers: {
          'Content-Type':'application/json',
        },
        data: {
          username: this.username,
          password: this.userPassword,
        },
      }).then((res) => {
        this.authToken = res.data.access_token;
        this.expiresAt = res.data.expires_at;
        options.headers['Authorization'] = `Bearer ${this.authToken}`;
        if (this.premise) {
          const selectedPremise =
          res.data.premises.find((premise: any) => premise.name === this.premise);
          if (selectedPremise) {
            const premiseOptions = {
              url: this.baseUrl + this.premiseUrl + selectedPremise.opid,
              method: 'GET',
              headers: {
                Authorization: `Bearer ${this.authToken}`,
              },
            };
            return this.backendSrv.datasourceRequest(premiseOptions)
              .then((premiseResponse: any) => {
                this.authToken = premiseResponse.data.access_token;
                options.headers['Authorization'] = `Bearer ${this.authToken}`;
                return this.backendSrv.datasourceRequest(options);
              });
          }
          const premiseNames = res.data.premises.map((premise => premise.name));
          return new Error(`Invalid Premise Name. Valid Premises : ${premiseNames.join(' , ')} `);
        }
        return this.backendSrv.datasourceRequest(options);
      });
    }
    if (options.headers) {
      options.headers = JSON.parse(JSON.stringify(options.headers));
      options.headers['Authorization'] = `Bearer ${this.authToken}`;
    }
    return this.backendSrv.datasourceRequest(options);
  }

  buildQueryTargets(options) {
    return options.targets
      .map((target) => {
        let data = isUndefined(target.data) ? null : target.data;

        if (typeof data === 'string' && data.trim() === '') {
          data = null;
        }

        if (data !== null) {
          const match = data.match(/("(\$.+?)")/g);
          if (match !== null) {
            data
              .match(/("(\$.+?)")/g)
              .map((match: string) => {
                const replacedMatch = this.templateSrv.replace(match, options.scopedVars, 'json');
                if (replacedMatch !== match) {
                  data = data.replace(match, replacedMatch.substring(1, replacedMatch.length - 1));
                }
              });
          }
          data = JSON.parse(data);
        }

        let targetValue = target.target;
        if (typeof targetValue === 'string') {
          targetValue = this.templateSrv.replace(
            target.target.toString(),
            options.scopedVars,
            'regex',
          );
        }

        return {
          data,
          target: targetValue,
          refId: target.refId,
          hide: target.hide,
          type: target.type,
        };
      });
  }

  getScopedVariables(scopedVars = {}) {
    const variables = JSON.parse(JSON.stringify(this.templateSrv.getVariables()));
    return variables.reduce((vars, variable) => {
      vars = JSON.parse(JSON.stringify(vars));
      if (scopedVars[variable.id] && typeof scopedVars[variable.id].text === 'string') {
        vars[variable.id].text = [scopedVars[variable.id].text];
        vars[variable.id].value = [scopedVars[variable.id].value];
        return vars;
      } 
      return {
        ...vars,
        [variable.id]: {
          selected: true,
          text: ( typeof variable.current.text === 'string' ) ? [variable.current.text] : variable.current.text,
          value: ( typeof variable.current.value === 'string' ) ? [variable.current.value] : variable.current.value,
        }
      }
    }, scopedVars);
  }

  getVariables() {
    const index = isUndefined(this.templateSrv.index) ? {} : this.templateSrv.index;
    const variables = {};
    Object.keys(index).forEach((key) => {
      const variable = index[key];

      let variableValue = variable.current.value;
      if (variableValue === '$__all' || isEqual(variableValue, ['$__all'])) {
        if (variable.allValue === null) {
          variableValue = variable.options.slice(1).map(textValuePair => textValuePair.value);
        } else {
          variableValue = variable.allValue;
        }
      }

      variables[key] = {
        text: variable.current.text,
        value: variableValue,
      };
    });

    return variables;
  }

  getTagKeys(options) {
    return new Promise((resolve, reject) => {
      this.doRequest({
        urlAppend: `/tag-keys`,
        method: 'POST',
        data: options,
      }).then((result) => {
        return resolve(result.data);
      });
    });
  }

  getTagValues(options) {
    return new Promise((resolve, reject) => {
      this.doRequest({
        urlAppend: `/tag-values`,
        method: 'POST',
        data: options,
      }).then((result) => {
        return resolve(result.data);
      });
    });
  }

}

